import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
# frame difference to detect motion
for t in [0,1,5,10,20,40,60,80,95]:
    if t==0:
        diff = np.abs(d[1]-d[0]).sum(-1)
    else:
        diff = np.abs(d[t]-d[0]).sum(-1)
    ys,xs=np.where(diff>30)
    if len(xs):
        print(t, 'n=',len(xs),'x',xs.min(),xs.max(),'y',ys.min(),ys.max())
    else:
        print(t,'none')
\""

